
// booking.js
// Small wrapper to send bookings to your real API.
// Configure the API base URL with REACT_APP_API_BASE in your environment (or window.__API_BASE__ at runtime).

// Define getApiBase function first
const getApiBase = () => {
  // Prefer explicit env var, then runtime override, then default to same-origin
  if (process.env.REACT_APP_API_BASE) return process.env.REACT_APP_API_BASE.replace(/\/$/, '');
  if (typeof window !== 'undefined' && window.__API_BASE__) return window.__API_BASE__.replace(/\/$/, '');
  return '';
};

export async function createBooking(payload) {
  const base = getApiBase();
  const url = (base ? base : '') + '/api/bookings';
  
  // Add debug logging to see what's happening
  console.log('API Base:', base);
  console.log('Full URL:', url);
  console.log('Payload:', payload);
  
  try {
    const res = await fetch(url, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json', 
        'Accept': 'application/json' 
      },
      // Only include credentials if needed
      credentials: base ? 'include' : 'same-origin',
      body: JSON.stringify(payload),
    });
    
    // Check if response has content before trying to parse
    const contentType = res.headers.get('content-type');
    let data = {};
    
    if (contentType && contentType.includes('application/json')) {
      data = await res.json();
    } else {
      const text = await res.text();
      console.warn('Non-JSON response:', text);
    }
    
    if (!res.ok) {
      return { 
        success: false, 
        error: data.error || `Server error: ${res.status} ${res.statusText}`,
        status: res.status 
      };
    }
    
    return { success: true, data };
  } catch (err) {
    console.error('Fetch error:', err);
    return { 
      success: false, 
      error: err.message || 'Network error' 
    };
  }
}

export async function getAvailability(date) {
  const base = getApiBase();
  const url = (base ? base : '') + '/api/availability?date=' + encodeURIComponent(date);
  
  console.log('Fetching availability from:', url);
  
  try {
    const res = await fetch(url, { 
      headers: { Accept: 'application/json' }, 
      credentials: base ? 'include' : 'same-origin' 
    });
    
    if (!res.ok) {
      return { 
        success: false, 
        error: `Failed to fetch availability: ${res.status} ${res.statusText}`, 
        status: res.status 
      };
    }
    
    const json = await res.json();
    return { success: true, data: json };
  } catch (err) {
    console.error('Availability fetch error:', err);
    return { 
      success: false, 
      error: err.message || 'Network error' 
    };
  }
}
